import React, { useState } from 'react';

function Auth({ onLogin }) {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);

    setTimeout(() => {
      const userData = {
        email: formData.email,
        name: isLogin 
          ? formData.email.split('@')[0].replace(/[._-]/g, ' ').replace(/\s+/g, ' ').replace(/\b\w/g, l => l.toUpperCase()).trim()
          : formData.name
      };

      localStorage.setItem('currentUser', JSON.stringify(userData));
      onLogin(userData);
      setLoading(false);
    }, 1500);
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h1>🍽️ Apsit Canteen</h1>
        <p>{isLogin ? 'Welcome! Please sign in to place your order' : 'Create your account to order from canteen'}</p>

        <form onSubmit={handleSubmit}>
          {!isLogin && (
            <div className="form-group">
              <label>Full Name</label>
              <input
                type="text"
                name="name"
                placeholder="Enter your full name"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>
          )}

          <div className="form-group">
            <label>Email Address</label>
            <input
              type="email"
              name="email"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Password</label>
            <input
              type="password"
              name="password"
              placeholder={isLogin ? "Enter your password" : "Create a password"}
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>

          <button type="submit" className="btn" disabled={loading}>
            {loading ? (isLogin ? '🔄 Signing In...' : '🔄 Creating Account...') : (isLogin ? 'Sign In' : 'Create Account')}
          </button>
        </form>

        <p>
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <span className="auth-switch" onClick={() => setIsLogin(!isLogin)}>
            {isLogin ? 'Sign up here' : 'Sign in here'}
          </span>
        </p>
      </div>
    </div>
  );
}

export default Auth;
